package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.JsonFactory;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import com.fasterxml.jackson.databind.ObjectCodec;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class ReaderBasedJsonParser__parseName_TriageGen0Test {

    private ReaderBasedJsonParser parser;
    private JsonFactory factory;
    private ObjectCodec codec;

    // Constant used in the method
    private static final int INT_QUOTE = '"';

    @Before
    public void setUp() throws Exception {
        factory = new JsonFactory();
        codec = factory.getCodec();
        // Note: ReaderBasedJsonParser is protected, we use a subclass or reflection if necessary.
        // However, since we are testing the method directly, we will instantiate it via a helper.
    }

    /**
     * Helper to instantiate the protected ReaderBasedJsonParser using reflection or a wrapper.
     */
    private ReaderBasedJsonParser createParser(String json) throws Exception {
        StringReader reader = new StringReader(json);
        // Using reflection to call the protected constructor
        java.lang.reflect.Constructor<ReaderBasedJsonParser> constructor = ReaderBasedJsonParser.class.getDeclaredConstructor(
                IOContext.class, int.class, java.io.Reader.class, ObjectCodec.class, CharsToNameCanonicalizer.class);
        constructor.setAccessible(true);

        return constructor.newInstance(
                IOContext.Empty.instance,
                0,
                reader,
                codec,
                new CharsToNameCanonicalizer()
        );
    }

    /**
     * Helper to invoke the protected _parseName method.
     */
    private String invokeParseName(ReaderBasedJsonParser parser, int i) throws Exception {
        Method method = ReaderBasedJsonParser.class.getDeclaredMethod("_parseName", int.class);
        method.setAccessible(true);
        return (String) method.invoke(parser, i);
    }

    /**
     * Helper to set internal fields for testing edge cases (ptr, inputEnd, etc.)
     */
    private void setInternalField(ReaderBasedJsonParser parser, String fieldName, Object value) throws Exception {
        Field field = ReaderBasedJsonParser.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(parser, value);
    }

    @Test
    public void testParseName_HandleOddName() throws Exception {
        // If i != INT_QUOTE, it calls _handleOddName
        ReaderBasedJsonParser parser = createParser("{");
        String result = invokeParseName(parser, 1); // 1 is not '"'
        // Since we don't know the exact implementation of _handleOddName, 
        // we expect it to behave according to its logic. 
        // In Jackson, this usually handles unquoted keys.
    }

    @Test
    public void testParseName_SimpleName_Success() throws Exception {
        // Test the "First" block: simple name, no escape, no buffer boundary crossing
        // JSON: {"name":1}
        ReaderBasedJsonParser parser = createParser("{\"name\":1}");

        // Manually advance to the start of the key
        parser.nextToken(); // Move to FIELD_NAME

        // We use reflection to call the protected method
        String name = invokeParseName(parser, INT_QUOTE);
        assertEquals("name", name);
    }

    @Test
    public void testParseName_NameWithBoundaryCrossing() throws Exception {
        // Test the "else" block where it falls through to _parseName2
        // This happens if the loop hits the end of the buffer or a non-Latin1 char
        // We simulate this by having a very short buffer or special characters
        ReaderBasedJsonParser parser = createParser("{\"a\":1}");

        // Force the ptr to the end of input to trigger the fallback
        Field ptrField = ReaderBasedJsonParser.class.getDeclaredField("_inputPtr");
        ptrField.setAccessible(true);
        Field endField = ReaderBasedJsonParser.class.getDeclaredField("_inputEnd");
        endField.setAccessible(true);

        ptrField.set(parser, 100); // Set ptr beyond end
        endField.set(parser, 10);

        // This should trigger the _parseName2 path
        try {
            invokeParseName(parser, INT_QUOTE);
        } catch (Exception e) {
            // Depending on _parseName2 implementation, it might throw EOF or error
        }
    }

    @Test
    public void testParseName_NonLatin1Char() throws Exception {
        // Test the loop breaking due to non-Latin1 characters
        // Using a character that would make codes[ch] == 0 or similar logic
        // In Jackson, _icLatin1 is used to check if char is simple ASCII/Latin1
        ReaderBasedJsonParser parser = createParser("{\"\u1234\":1}");
        parser.nextToken();

        String name = invokeParseName(parser, INT_QUOTE);
        assertEquals("\u1234", name);
    }

    @Test
    public void testParseName_QuoteAtStart() throws Exception {
        // Test the case where ch == '"' is found immediately
        ReaderBasedJsonParser parser = createParser("{\"\"\":1}");
        parser.nextToken();

        // This tests: if (ch == '"') { ... return _symbols.findSymbol(...) }
        String name = invokeParseName(parser, INT_QUOTE);
        assertEquals("", name);
    }

    @Test
    public void testParseName_EmptyBuffer() throws Exception {
        ReaderBasedJsonParser parser = createParser("");

        Field ptrField = ReaderBasedJsonParser.class.getDeclaredField("_inputPtr");
        ptrField.setAccessible(true);
        Field endField = ReaderBasedJsonParser.class.getDeclaredField("_inputEnd");
        endField.setAccessible(true);

        ptrField.set(parser, 0);
        endField.set(parser, 0);

        try {
            invokeParseName(parser, INT_QUOTE);
        } catch (Exception e) {
            // Expected to fail or return null/empty via _parseName2
        }
    }
}
